class CelestialDrift : public Pattern<RGBA>
{
    PixelMap::Polar *map;
    Transition transition = Transition(800, 1500);
    LFO<SinFast> breathLfo;
    LFO<SawUp> spinLfo;
    LFO<Glow> pulseLfo;
    LFO<SinFast> wobbleLfo;
    Permute perm;
    FadeDown fade = FadeDown(1200);
    BeatWatcher watcher;

public:
    CelestialDrift(PixelMap *map)
    {
        this->map = map->toPolar();
        this->name = "Celestial drift";
    }

    inline void Calculate(RGBA *pixels, int width, bool active, Params *params) override
    {
        if (!transition.Calculate(active))
            return;

        float velocity = params->getVelocity(12000, 2000);
        float size = params->getSize(0.8, 0.15);
        float amount = params->getAmount(2, 6);
        float offset = params->getOffset(0, 0.5);
        float variant = params->getVariant();
        float intensity = params->getIntensity(0.3, 1.0);

        spinLfo.setPeriod(velocity);
        breathLfo.setPeriod(velocity * 1.7);
        pulseLfo.setPeriod(velocity * 0.6);
        pulseLfo.setDutyCycle(0.4);
        wobbleLfo.setPeriod(velocity * 2.3);

        if (watcher.Triggered())
            fade.reset();

        perm.setSize(width);

        float spin = spinLfo.getValue();
        float wobble = wobbleLfo.getValue() * 0.3 * variant;

        for (int i = 0; i < std::min(width, (int)map->size()); i++)
        {
            float r = map->r(i);
            float th = map->th(i) / (2.0f * M_PI);

            float angularPhase = th + spin + r * wobble;
            float arms = 0;
            for (int a = 0; a < (int)amount; a++)
            {
                float armOffset = (float)a / amount + offset * a * 0.1f;
                float dist = angularPhase - armOffset;
                dist = dist - (int)dist;
                if (dist < 0) dist += 1.0f;
                if (dist > 0.5f) dist = 1.0f - dist;
                float armBrightness = Utils::constrain_f(1.0f - dist / size, 0.0f, 1.0f);
                armBrightness *= armBrightness;
                arms = std::max(arms, armBrightness);
            }

            float radialPulse = breathLfo.getValue(r * 0.3f);
            float coreBrightness = Utils::constrain_f(1.0f - r / (size * 3.0f), 0.0f, 1.0f);
            coreBrightness *= coreBrightness * pulseLfo.getValue(0.0f);

            float gradientPos = Utils::constrain_f(th + r * 0.5f + spin * 0.5f, 0.0f, 1.0f);
            RGBA armColor = params->getGradient(gradientPos);
            RGBA coreColor = params->getHighlightColor();

            float radialFade = Utils::constrain_f(1.0f - r * (1.0f - radialPulse * 0.4f), 0.2f, 1.0f);

            float beatFlash = fade.getValue() * 0.3f * intensity;
            float finalBrightness = (arms * radialFade + coreBrightness + beatFlash) * transition.getValue();
            finalBrightness = Utils::constrain_f(finalBrightness, 0.0f, 1.0f);

            pixels[i] = armColor * (arms * radialFade * transition.getValue());
            pixels[i] += coreColor * (coreBrightness * transition.getValue());
            pixels[i] += params->getPrimaryColor() * (beatFlash * transition.getValue());
        }
    }
};
typedef CelestialDrift VibePattern;
